// electron/services/meeting/sectionInstructions.ts
//
// Shipped extraction instructions for every built-in note section (2026-11-16).
//
// A built-in section's title and description are constants, the same for every user, so
// its instruction is written once here and reviewed, instead of being compiled by an AI
// call on each user's machine (that was 56 calls at first launch, more with failing keys).
// User-written sections (added or edited in Modes settings) still compile at save time
// (ModesManager -> SectionPromptCompiler) and are stored in mode_note_sections.compiled_prompt.
//
// Three sources of built-in text, all covered:
//   - ModesManager TEMPLATE_NOTE_SECTIONS (a mode's sections when it is created);
//   - noteTemplates.ts NOTE_TEMPLATES ("Use a template", and templates picked in the notepad);
//   - the older sets DatabaseManager migrations v12/v13 wrote, still in users' databases. The
//     default General mode on a new install gets v12's three sections.
//
// Keyed by the EXACT title + description, so a section the user edited no longer matches
// and uses its own compiled instruction. The test
// BuiltinSectionInstructions2026_11_16.test.mjs fails when a section from any of the three
// has no entry here, or an entry here matches none: change the key with the section text.
//
// The instructions say what counts, what to leave out and the bullet shape. They do not
// repeat the chunk prompt's own rules (only the transcript, evidence, omit a section with
// nothing in it), and never ask for "Not discussed" or "NA", which those rules forbid.
//
// Pure data, no imports. Platform-independent.

export interface BuiltinSectionInstruction {
    title: string;
    description: string;
    instruction: string;
}

