const keyOf = (title: string, description: string): string => `${title.trim()}\u0000${(description || '').trim()}`;
const BY_KEY: ReadonlyMap<string, string> = new Map(BUILTIN_SECTION_INSTRUCTIONS.map(s => [keyOf(s.title, s.description), s.instruction]));

/** The shipped instruction for a built-in section, or undefined when the text is not built-in (edited or user-written). */
export function builtinSectionInstruction(title: string, description: string | undefined): string | undefined {
    return BY_KEY.get(keyOf(title || '', description || ''));
}

/**
 * The instruction the notes prompt gives for one section: the shipped one when the section
 * is built-in and unedited, else the one compiled for the user's own text, else its
 * description, else a bare fallback.
 */
export function sectionGuidance(section: { title: string; description?: string; compiledPrompt?: string }): string {
    return builtinSectionInstruction(section.title, section.description)
        ?? (section.compiledPrompt?.trim()
            || section.description?.trim()
            || `Capture content for "${section.title}", grounded only in this transcript.`);
}
